<div class="row g-3"><div class="col-md-6"><label class="form-label">Address label</label><select class="form-select" name="label"><?php $__currentLoopData = ['home'=>'Home','office'=>'Office','other'=>'Other']; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $value=>$label): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><option value="<?php echo e($value); ?>" <?php if(old('label',$address?->label ?? 'home')===$value): echo 'selected'; endif; ?>><?php echo e($label); ?></option><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></select></div><div class="col-md-6"><label class="form-label">Full name</label><input class="form-control" name="name" value="<?php echo e(old('name',$address?->name ?? $customer->full_name)); ?>" required></div><div class="col-md-6"><label class="form-label">Phone</label><input class="form-control" name="phone" value="<?php echo e(old('phone',$address?->phone ?? $customer->phone)); ?>" required></div><div class="col-md-6"><label class="form-label">Area</label><input class="form-control" name="area" value="<?php echo e(old('area',$address?->area)); ?>"></div><div class="col-12"><label class="form-label">Address</label><textarea class="form-control" rows="3" name="address" required><?php echo e(old('address',$address?->address)); ?></textarea></div><div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="is_default" value="1" <?php if(old('is_default',$address?->is_default)): echo 'checked'; endif; ?>> Set as default address</label></div></div>
